[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>SnapFrame — Capture, Create & Share What You Love</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    :root {
      --bg-page: oklch(98% 0.01 265);
      --bg-surface: oklch(100% 0 0);
      --text-primary: oklch(15% 0.02 265);
      --text-secondary: oklch(50% 0.02 265);
      --accent-purple: oklch(55% 0.25 290);
      --accent-orange: oklch(70% 0.20 45);
      --accent-magenta: oklch(60% 0.22 320);
      --safety-teal: oklch(75% 0.08 160);
      --gradient-hero: linear-gradient(135deg, oklch(55% 0.25 290) 0%, oklch(60% 0.22 320) 50%, oklch(70% 0.20 45) 100%);
      --radius-sm: 8px;
      --radius-md: 16px;
      --radius-lg: 24px;
      --shadow-card: 0 4px 24px oklch(0% 0 0 / 0.08);
      --shadow-hover: 0 8px 40px oklch(0% 0 0 / 0.12);
      --max-width: 1200px;
      --header-height: 72px;
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
      background: var(--bg-page);
      color: var(--text-primary);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
    }

    a {
      color: inherit;
      text-decoration: none;
    }

    img {
      max-width: 100%;
      display: block;
    }

    .container {
      max-width: var(--max-width);
      margin: 0 auto;
      padding: 0 24px;
    }

    /* Header */
    .header {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      height: var(--header-height);
      z-index: 1000;
      transition: background 0.3s ease, box-shadow 0.3s ease;
    }

    .header.scrolled {
      background: var(--bg-surface);
      box-shadow: 0 1px 0 oklch(0% 0 0 / 0.08);
    }

    .header-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 100%;
    }

    .logo {
      font-size: 24px;
      font-weight: 800;
      letter-spacing: -0.02em;
      background: var(--gradient-hero);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }

    .header-nav {
      display: flex;
      align-items: center;
      gap: 32px;
    }

    .nav-links {
      display: flex;
      gap: 32px;
      list-style: none;
    }

    .nav-links a {
      font-weight: 500;
      font-size: 15px;
      color: var(--text-secondary);
      transition: color 0.2s ease;
    }

    .nav-links a:hover {
      color: var(--text-primary);
    }

    .btn-login {
      font-weight: 600;
      font-size: 15px;
      padding: 10px 20px;
      border-radius: var(--radius-sm);
      background: var(--text-primary);
      color: var(--bg-surface);
      transition: transform 0.2s ease, opacity 0.2s ease;
    }

    .btn-login:hover {
      transform: scale(1.02);
    }

    .hamburger {
      display: none;
      flex-direction: column;
      gap: 5px;
      background: none;
      border: none;
      cursor: pointer;
      padding: 8px;
      z-index: 1001;
    }

    .hamburger span {
      display: block;
      width: 24px;
      height: 2px;
      background: var(--text-primary);
      border-radius: 2px;
      transition: transform 0.3s ease, opacity 0.3s ease;
    }

    .hamburger.active span:nth-child(1) {
      transform: translateY(7px) rotate(45deg);
    }

    .hamburger.active span:nth-child(2) {
      opacity: 0;
    }

    .hamburger.active span:nth-child(3) {
      transform: translateY(-7px) rotate(-45deg);
    }

    /* Mobile Navigation Overlay */
    .mobile-nav {
      display: none;
      position: fixed;
      inset: 0;
      background: var(--bg-surface);
      z-index: 999;
      padding-top: var(--header-height);
      opacity: 0;
      visibility: hidden;
      transition: opacity 0.3s ease, visibility 0.3s ease;
    }

    .mobile-nav.active {
      opacity: 1;
      visibility: visible;
    }

    .mobile-nav-links {
      list-style: none;
      padding: 24px;
      display: flex;
      flex-direction: column;
      gap: 8px;
    }

    .mobile-nav-links a {
      display: block;
      padding: 16px 0;
      font-size: 20px;
      font-weight: 600;
      border-bottom: 1px solid oklch(0% 0 0 / 0.06);
    }

    .mobile-nav .btn-login {
      margin: 24px;
      text-align: center;
    }

    /* Hero Section */
    .hero {
      min-height: 100vh;
      display: flex;
      align-items: center;
      justify-content: center;
      text-align: center;
      padding: 120px 24px 80px;
      position: relative;
      overflow: hidden;
    }

    .hero::before {
      content: '';
      position: absolute;
      inset: 0;
      background:
        radial-gradient(ellipse 80% 60% at 50% 0%, oklch(55% 0.25 290 / 0.15) 0%, transparent 60%),
        radial-gradient(ellipse 60% 50% at 80% 80%, oklch(70% 0.20 45 / 0.10) 0%, transparent 50%),
        radial-gradient(ellipse 50% 40% at 20% 70%, oklch(60% 0.22 320 / 0.10) 0%, transparent 50%);
      z-index: 0;
    }

    .hero-content {
      position: relative;
      z-index: 1;
      max-width: 800px;
    }

    .hero h1 {
      font-size: clamp(36px, 6vw, 64px);
      font-weight: 800;
      line-height: 1.1;
      letter-spacing: -0.03em;
      margin-bottom: 24px;
    }

    .hero p {
      font-size: 20px;
      color: var(--text-secondary);
      max-width: 600px;
      margin: 0 auto 40px;
    }

    .btn-primary {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 16px 32px;
      font-size: 17px;
      font-weight: 700;
      border-radius: var(--radius-lg);
      background: var(--gradient-hero);
      color: white;
      transition: transform 0.2s ease, box-shadow 0.2s ease;
      box-shadow: 0 4px 20px oklch(55% 0.25 290 / 0.3);
    }

    .btn-primary:hover {
      transform: scale(1.03);
      box-shadow: 0 6px 30px oklch(55% 0.25 290 / 0.4);
    }

    /* Section Styles */
    section {
      padding: 80px 0;
    }

    .section-label {
      display: inline-block;
      font-size: 13px;
      font-weight: 700;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      margin-bottom: 16px;
      background: var(--gradient-hero);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }

    .section-title {
      font-size: clamp(28px, 4vw, 42px);
      font-weight: 800;
      letter-spacing: -0.02em;
      line-height: 1.2;
      margin-bottom: 16px;
    }

    .section-desc {
      font-size: 18px;
      color: var(--text-secondary);
      max-width: 600px;
      line-height: 1.7;
    }

    .section-link {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      margin-top: 24px;
      font-weight: 600;
      font-size: 16px;
      color: var(--accent-purple);
      transition: gap 0.2s ease;
    }

    .section-link:hover {
      gap: 10px;
    }

    /* Features Section */
    .features {
      background: var(--bg-surface);
    }

    .features-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 24px;
      align-items: center;
    }

    .feature-card {
      padding: 48px;
      border-radius: var(--radius-lg);
      background: var(--bg-page);
      border: 1px solid oklch(0% 0 0 / 0.06);
    }

    .feature-card.highlight {
      background: linear-gradient(135deg, var(--accent-purple), oklch(60% 0.22 320));
      color: white;
      border: none;
    }

    .feature-card.highlight .section-desc {
      color: oklch(100% 0 0 / 0.8);
    }

    .feature-icon {
      width: 56px;
      height: 56px;
      border-radius: var(--radius-md);
      background: oklch(100% 0 0 / 0.1);
      display: flex;
      align-items: center;
      justify-content: center;
      margin-bottom: 24px;
      font-size: 24px;
    }

    .feature-card.highlight .feature-icon {
      background: oklch(100% 0 0 / 0.2);
    }

    /* Safety Section */
    .safety {
      background: linear-gradient(180deg, oklch(75% 0.04 160 / 0.05) 0%, var(--bg-page) 100%);
    }

    .safety-content {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 64px;
      align-items: center;
    }

    .safety-text .section-label {
      color: var(--safety-teal);
      -webkit-text-fill-color: var(--safety-teal);
    }

    .safety-image {
      border-radius: var(--radius-lg);
      overflow: hidden;
      aspect-ratio: 4/3;
      background: linear-gradient(135deg, var(--safety-teal), oklch(70% 0.15 180));
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .safety-image-inner {
      width: 120px;
      height: 120px;
      border-radius: 50%;
      background: oklch(100% 0 0 / 0.2);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 48px;
    }

    /* Creators Section */
    .creators {
      background: var(--bg-surface);
      overflow: hidden;
    }

    .creators-content {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 64px;
      align-items: center;
    }

    .creators-text .section-label {
      color: var(--accent-magenta);
      -webkit-text-fill-color: var(--accent-magenta);
    }

    .creators-visual {
      position: relative;
      border-radius: var(--radius-lg);
      overflow: hidden;
      aspect-ratio: 4/3;
      background: linear-gradient(135deg, oklch(55% 0.25 290), var(--accent-magenta), var(--accent-orange));
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .creators-visual-inner {
      width: 100px;
      height: 100px;
      border-radius: 50%;
      background: oklch(100% 0 0 / 0.2);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 40px;
    }

    /* Tagline Banner */
    .tagline-banner {
      padding: 48px 0;
      background: var(--gradient-hero);
      text-align: center;
    }

    .tagline-banner h2 {
      font-size: clamp(24px, 4vw, 36px);
      font-weight: 700;
      color: white;
      letter-spacing: -0.02em;
    }

    /* News Section */
    .news {
      padding: 80px 0;
    }

    .news-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 32px;
      flex-wrap: wrap;
      gap: 16px;
    }

    .news-scroll {
      display: flex;
      gap: 20px;
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      -webkit-overflow-scrolling: touch;
      padding-bottom: 16px;
      scrollbar-width: none;
      -ms-overflow-style: none;
    }

    .news-scroll::-webkit-scrollbar {
      display: none;
    }

    .news-card {
      flex: 0 0 320px;
      scroll-snap-align: start;
      background: var(--bg-surface);
      border-radius: var(--radius-md);
      overflow: hidden;
      border: 1px solid oklch(0% 0 0 / 0.06);
      transition: transform 0.2s ease, box-shadow 0.2s ease;
      cursor: grab;
    }

    .news-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-hover);
    }

    .news-card:active {
      cursor: grabbing;
    }

    .news-thumb {
      aspect-ratio: 16/9;
      background: linear-gradient(135deg, oklch(55% 0.15 290), oklch(70% 0.12 320));
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .news-thumb-icon {
      font-size: 32px;
      opacity: 0.6;
    }

    .news-card-body {
      padding: 20px;
    }

    .news-tags {
      display: flex;
      gap: 8px;
      flex-wrap: wrap;
      margin-bottom: 12px;
    }

    .news-tag {
      font-size: 11px;
      font-weight: 700;
      padding: 4px 10px;
      border-radius: 100px;
      background: oklch(55% 0.15 290 / 0.1);
      color: var(--accent-purple);
    }

    .news-card-title {
      font-size: 16px;
      font-weight: 600;
      line-height: 1.4;
      margin-bottom: 8px;
      display: -webkit-box;
      -webkit-line-clamp: 2;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }

    .news-date {
      font-size: 13px;
      color: var(--text-secondary);
    }

    .view-more {
      font-weight: 600;
      font-size: 15px;
      color: var(--accent-purple);
      display: flex;
      align-items: center;
      gap: 6px;
      transition: gap 0.2s ease;
    }

    .view-more:hover {
      gap: 10px;
    }

    /* CTA Download Section */
    .cta-download {
      background: var(--text-primary);
      color: white;
      text-align: center;
      padding: 80px 24px;
    }

    .cta-download h2 {
      font-size: clamp(28px, 5vw, 48px);
      font-weight: 800;
      letter-spacing: -0.02em;
      margin-bottom: 8px;
    }

    .cta-download p {
      font-size: 20px;
      opacity: 0.8;
      margin-bottom: 32px;
    }

    .store-buttons {
      display: flex;
      gap: 16px;
      justify-content: center;
      flex-wrap: wrap;
    }

    .store-btn {
      display: flex;
      align-items: center;
      gap: 12px;
      padding: 14px 24px;
      background: white;
      color: var(--text-primary);
      border-radius: var(--radius-md);
      font-weight: 600;
      transition: transform 0.2s ease;
    }

    .store-btn:hover {
      transform: scale(1.03);
    }

    .store-btn-icon {
      font-size: 24px;
    }

    .store-btn-text {
      text-align: left;
      line-height: 1.2;
    }

    .store-btn-text span {
      display: block;
      font-size: 11px;
      font-weight: 400;
    }

    /* Footer */
    .footer {
      background: var(--bg-surface);
      border-top: 1px solid oklch(0% 0 0 / 0.06);
      padding: 64px 0 32px;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: repeat(6, 1fr);
      gap: 32px;
      margin-bottom: 48px;
    }

    .footer-col h4 {
      font-size: 13px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.05em;
      margin-bottom: 16px;
      color: var(--text-primary);
    }

    .footer-col ul {
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 10px;
    }

    .footer-col a {
      font-size: 14px;
      color: var(--text-secondary);
      transition: color 0.2s ease;
    }

    .footer-col a:hover {
      color: var(--text-primary);
    }

    .footer-col a.external::after {
      content: ' ↗';
      font-size: 11px;
    }

    .footer-bottom {
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding-top: 32px;
