  <script>
    // Header scroll effect
    const header = document.getElementById('header');
    window.addEventListener('scroll', () => {
      if (window.scrollY > 50) {
        header.classList.add('scrolled');
      } else {
        header.classList.remove('scrolled');
      }
    });

    // Hamburger menu toggle
    const hamburger = document.getElementById('hamburger');
    const mobileNav = document.getElementById('mobileNav');

    hamburger.addEventListener('click', () => {
      hamburger.classList.toggle('active');
      mobileNav.classList.toggle('active');
      document.body.style.overflow = mobileNav.classList.contains('active') ? 'hidden' : '';
    });

    // Close mobile nav when clicking a link
    document.querySelectorAll('.mobile-nav-links a').forEach(link => {
      link.addEventListener('click', () => {
        hamburger.classList.remove('active');
        mobileNav.classList.remove('active');
        document.body.style.overflow = '';
      });
    });

    // News carousel - horizontal scroll with momentum
    const newsScroll = document.getElementById('newsScroll');
    let isDown = false;
    let startX;
    let scrollLeft;

    newsScroll.addEventListener('mousedown', (e) => {
      isDown = true;
      newsScroll.style.cursor = 'grabbing';
      startX = e.pageX - newsScroll.offsetLeft;
      scrollLeft = newsScroll.scrollLeft;
    });

    newsScroll.addEventListener('mouseleave', () => {
      isDown = false;
      newsScroll.style.cursor = 'grab';
    });

    newsScroll.addEventListener('mouseup', () => {
      isDown = false;
      newsScroll.style.cursor = 'grab';
    });

    newsScroll.addEventListener('mousemove', (e) => {
      if (!isDown) return;
      e.preventDefault();
      const x = e.pageX - newsScroll.offsetLeft;
      const walk = (x - startX) * 2;
      newsScroll.scrollLeft = scrollLeft - walk;
    });

    // Touch support for mobile swipe
    let touchStartX = 0;
    let touchScrollLeft = 0;

    newsScroll.addEventListener('touchstart', (e) => {
      touchStartX = e.touches[0].pageX;
      touchScrollLeft = newsScroll.scrollLeft;
    }, { passive: true });

    newsScroll.addEventListener('touchmove', (e) => {
      const delta = touchStartX - e.touches[0].pageX;
      newsScroll.scrollLeft = touchScrollLeft + delta;
    }, { passive: true });
  </script>
